window.combatBenchState = function(){
  var alive = 0;
  for(var i=0;i<G.enemies.length;i++){ if(!G.enemies[i].dead) alive++; }
  return {
    ready: !!G.ready,
    playerAlive: (P.hp > 0) && !G.over,
    enemyCount: alive,
    hitCount: G.hitCount,
    limbBreakCount: G.breakCount,
